steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(first: 10, filter: {
        search: {query: \"checkout hangs guest users Safari\"},
        assignee: {
          contains: \"Priya Nair\"
        }
      }) {
        nodes {
          id
          identifier
          title
          url
          priority
          priorityName
          team {
            name
          }
          assignee {
            name
          }
          milestone {
            name
          }
          project {
            name
          }
        }
      }
    }"
  }'
